{
  "tables": ["cards", "sets"],
  "columns": ["cards.id", "sets.code"],
  "filters": [
    {"table": "cards", "column": "originalreleasedate", "op": "LIKE", "value": "2014%"},
    {"table": "cards", "column": "setcode", "op": "IN", "value": "(SELECT code FROM sets WHERE mtgocode IS NOT NULL)"}
  ]
}

{
  "tables": ["sets", "cards"],
  "columns": ["sets.id", "sets.name", "sets.totalsetsize"],
  "filters": [
    {"table": "sets", "column": "type", "op": "=", "value": "Commander"},
    {"table": "sets", "column": "releasedate", "op": ">=", "value": "2020-01-01"},
    {"table": "sets", "column": "releasedate", "op": "<=", "value": "2020-12-31"},
    {"table": "cards", "column": "setcode", "op": "IN", "value": "(SELECT code FROM sets WHERE type = 'Commander' AND releasedate BETWEEN '2020-01-01' AND '2020-12-31')"},
    {"table": "cards", "column": "isnonfoil", "op": "=", "value": 1},
    {"table": "cards", "column": "isfoil", "op": "=", "value": 1},
    {"table": "cards", "column": "isonlineonly", "op": "=", "value": 0}
  ]
}

