    {"table": "customers", "column": "currency", "op": "=", "value": "CZK"},
    {"table": "customers", "column": "currency", "op": "=", "value": "EUR"},
    {"table": "yearmonth", "column": "date", "op": "like", "value": "2012%"},
    {"table": "yearmonth", "column": "date", "op": "like", "value": "2012%"},
    {"table": "yearmonth", "column": "customerid", "op": "in", "value": "SELECT customerid FROM customers WHERE currency = 'CZK'"},
    {"table": "yearmonth", "column": "customerid", "op": "in", "value": "SELECT customerid FROM customers WHERE currency = 'EUR'"}
  ]
}

